import { parseArguments } from './lib/argparse_like.mjs';
import { CliExit, KeyAndValueDuplicationError, ValueDuplicationError } from './lib/errors.mjs';
import { OrderedBidict } from './lib/ordered_bidict.mjs';

class BidictFailure extends Error {
  constructor(cause, lineNumber) {
    super(cause.message);
    this.name = 'BidictFailure';
    this.cause = cause;
    this.lineNumber = lineNumber;
  }
}

function writeLine(text) {
  process.stdout.write(`${String(text)}\n`);
}

function writeError(text) {
  process.stderr.write(`${text}\n`);
}

function setWithSourceLine(bidictInstance, key, value, lineNumber) {
  try {
    bidictInstance.set(key, value);
  } catch (error) {
    if (error instanceof ValueDuplicationError || error instanceof KeyAndValueDuplicationError) {
      throw new BidictFailure(error, lineNumber);
    }

    throw error;
  }
}

function formatBidictFailure(error, lineNumber) {
  return `Traceback (most recent call last):\n  File "test8.py", line ${lineNumber}, in <module>\nbidict.${error.name}: ${error.message}`;
}

function main() {
  const args = parseArguments(process.argv);
  const b = new OrderedBidict();

  setWithSourceLine(b, args.k1, args.v1, 15);
  setWithSourceLine(b, args.k2, args.v2, 16);
  setWithSourceLine(b, args.k3, args.v3, 17);

  writeLine(b.toString());
  writeLine(b.get(args.k1).toString());
  writeLine(b.inv[args.v2]);
  writeLine(b.inv[args.v3]);

  setWithSourceLine(b, args.k1, 999n, 26);
  writeLine(b.toString());
}

try {
  main();
} catch (error) {
  if (error instanceof CliExit) {
    if (error.stream === 'stdout') {
      writeLine(error.text);
    } else {
      writeError(error.text);
    }
    process.exitCode = error.exitCode;
  } else if (error instanceof BidictFailure) {
    writeError(formatBidictFailure(error.cause, error.lineNumber));
    process.exitCode = 1;
  } else {
    throw error;
  }
}

