      entry.value = normalizedValue;
      entry.valueText = valueText;
      this._valueIndex[valueText] = keyIndex;
      return;
    }

    const newIndex = this._entries.length;
    this._entries.push({ key, value: normalizedValue, valueText });
    this._keyIndex[key] = newIndex;
    this._valueIndex[valueText] = newIndex;
  }

  get(key) {
    if (!hasOwn(this._keyIndex, key)) {
      return undefined;
    }

    return this._entries[this._keyIndex[key]].value;
  }

  _getKeyByValueText(valueText) {
    if (!hasOwn(this._valueIndex, valueText)) {
      return undefined;
    }

    return this._entries[this._valueIndex[valueText]].key;
  }

  toString() {
    const body = this._entries
      .map((entry) => `${pythonStringRepr(entry.key)}: ${entry.valueText}`)
      .join(', ');

    return `bidict({${body}})`;
  }
}
